import "core-js/modules/es6.number.constructor";
import { subnetList } from "@/api/operation/safeaccess/subnet";
import { getDictList as _getDictList, getDictCmdbList as _getDictCmdbList } from "@/api/dict";
export default {
  props: {
    disabled: {
      type: Boolean,
      default: false
    },
    placeholder: {
      type: String
    },
    value: {
      type: [String, Number, Array],
      default: ""
    },
    formIndex: {
      type: Number,
      default: -1
    },
    networkType: {
      type: String
    },
    institutionCode: {
      type: String
    }
  },
  watch: {
    value: function value(val) {
      this.myValue = val;
      this.$emit("input", val);
    }
  },
  data: function data() {
    return {
      codeList: [{
        dictValue: '0',
        dictKey: '正常'
      }, {
        dictValue: '1',
        dictKey: '停用'
      }],
      isPublicList: [{
        dictValue: '0',
        dictKey: '否'
      }, {
        dictValue: '1',
        dictKey: '是'
      }],
      deviceSourceList: [],
      deviceCategoryList: [],
      deviceTypeList: [],
      voltageLevelList: [],
      swStateList: [],
      Is802List: [],
      isAccessSwitchList: [],
      isShow: false,
      searchForm: {
        current: 1,
        size: 20
      },
      // 表格
      tableData: [],
      tableHeight: '450px',
      tableLoading: false,
      total: 0,
      selectList: [],
      list: [],
      myValue: this.value
    };
  },
  created: function created() {
    // 设置页面元素高度
    // this.setPageContentHeight()
    // 设置表格高度
    // this.setTableHeight()
    this.getList();

    //加载字典--工单状态
    // //加载字典--WBS元素
    this.getDictList("is3");
    //加载字典--入库仓库
    this.getDictList("swState");
    //加载字典--WBS项目
    this.getDictList("Is802");
    //加载字典--i6000同步状态
    this.getDictList("isAccessSwitch");
    //加载字典--i6000同步状态
    this.getDictList("is_to_i6000");
    // 加载字典
    this.getDictCmdbList('1102860579569664'); // 设备来源
    this.getDictCmdbList('1097745625841664'); // 设备分类
    this.getDictCmdbList('1097745969774592'); // 设备类型
    this.getDictCmdbList('1084068218601472'); // 电压等级
  },
  methods: {
    getDictCmdbList: function getDictCmdbList(ciId) {
      var _this = this;
      //加载字典
      _getDictCmdbList({
        ciId: ciId
      }).then(function (res) {
        if (ciId === '1102860579569664') {
          // 设备来源
          _this.deviceSourceList = res.data;
        } else if (ciId === '1097745625841664') {
          // 设备分类
          _this.deviceCategoryList = res.data;
        } else if (ciId === '1097745969774592') {
          // 设备类型
          _this.deviceTypeList = res.data;
        } else if (ciId === '1084068218601472') {
          // 电压等级
          _this.voltageLevelList = res.data;
        }
      });
    },
    getDictList: function getDictList(code) {
      var _this2 = this;
      //加载字典
      _getDictList(code).then(function (res) {
        if (code === 'swState') {
          _this2.swStateList = res.data;
        } else if (code === 'Is802') {
          _this2.Is802List = res.data;
        } else if (code === 'isAccessSwitch') {
          _this2.isAccessSwitchList = res.data;
        }
      });
    },
    showDictLable: function showDictLable(code, dictList) {
      //字典回显
      if (dictList != null && code !== '') {
        var items = dictList.filter(function (item) {
          return item.dictKey == code;
        });
        if (items != null && items.length > 0) {
          return items[0].dictValue;
        }
      }
      return code;
    },
    select: function select(val) {
      this.selectList = val;
    },
    handleClick: function handleClick() {
      if (!this.disabled) {
        this.isShow = true;
        this.getList();
      }
    },
    // 设置表格高度
    setTableHeight: function setTableHeight() {
      var pageBody = document.getElementsByClassName('page_body');
      this.tableHeight = pageBody[0].offsetHeight - 50 - 60 + 'px';
    },
    getList: function getList() {
      var _this3 = this;
      this.tableLoading = true;
      if (this.networkType) {
        this.searchForm.networkType = this.networkType;
      }
      if (this.institutionCode) {
        this.searchForm.institutionCode = this.institutionCode;
      }
      subnetList(this.searchForm).then(function (res) {
        _this3.tableData = res.data.records;
        _this3.total = res.data.total;
        _this3.tableLoading = false;
      }).catch(function () {
        _this3.tableLoading = false;
      });
    },
    handleSubmit: function handleSubmit() {
      if (this.selectList.length != 1) {
        this.$message.warning("请选择一条数据!");
        return;
      }
      this.$emit("input", this.selectList[0].subnetName);
      this.$emit("change", this.selectList[0], this.formIndex);
      this.isShow = false;
    },
    handleSEmpty: function handleSEmpty() {
      this.$emit("input", '');
      this.$emit("change", {});
      this.isShow = false;
    },
    // 查询
    handleQuery: function handleQuery() {
      this.searchForm.current = 1;
      this.getList();
    },
    // 重置
    searchReset: function searchReset() {
      this.searchForm = {
        current: 1,
        size: 20
      };
      this.getList();
    },
    handleSave: function handleSave(row) {
      //保存
      this.$emit("input", row.subnetName);
      this.$emit("change", row);
      this.isShow = false;
    }
  }
};
